<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/SOAPDomainMsg.xsd" var="var1"/>
    <input path="/Fund_Transfer_Wsdl_InlineSchema1.xsd" var="var"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/SOAPDomainMsg.xsd" var="var2"/>
    <namespaces>
        <namespace kind="supplement" prefix="io" uri="http://www.example.org/Fund_Transfer_Wsdl/"/>
        <namespace kind="extension" prefix="xs" uri="http://www.w3.org/2001/XMLSchema"/>
        <namespace kind="extension" prefix="fn" uri="http://www.w3.org/2005/xpath-functions"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="FundTransferDataMapping">
        <input path="$var1/mb:msg(SOAP_Domain_Msg,assembly,SOAP,Properties)" var="MessageAssembly">
            <cast path="$MessageAssembly/SOAP_Domain_Msg/Body/any" qualifier="{http://www.example.org/Fund_Transfer_Wsdl/}FundTransferRequest" ref="var"/>
        </input>
        <output path="$var2/mb:msg(SOAP_Domain_Msg,assembly,SOAP,Properties)" var="MessageAssembly2">
            <cast path="$MessageAssembly2/SOAP_Domain_Msg/Body/any" qualifier="{http://www.example.org/Fund_Transfer_Wsdl/}FundTransferResponse" ref="var"/>
        </output>
        <move>
            <input path="$MessageAssembly/Properties"/>
            <output path="$MessageAssembly2/Properties"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Body/FundTransferRequest/FundTransferTransctionType/TRXID"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/TRXID"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Body/FundTransferRequest/FundTransferTransctionType/TRXID"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/MSGID"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Body/FundTransferRequest/FundTransferTransctionType/TRXID"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/TransactionId"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Header"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Header"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Context"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Context"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Body/FundTransferRequest/FundTransferTransctionType/TransactionDate"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/TransactionDate"/>
        </move>
        <move>
            <input path="$MessageAssembly/SOAP_Domain_Msg/Body/FundTransferRequest/FundTransferTransctionType/TransactionDescription"/>
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/TransactionDescription"/>
        </move>
        <function ref="fn:current-time">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/TransactionTime"/>
        </function>
        <assign value="Transaction processed successfully.">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/Message"/>
        </assign>
        <function ref="fn:local-name">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/Application"/>
        </function>
        <assign value="Success">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/successIndicator"/>
        </assign>
        <assign value="FundTransfer">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/Service"/>
        </assign>
        <assign value="SUCCESS">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/TransactionStatus"/>
        </assign>
        <assign value="Data transfer Successfully">
            <output path="$MessageAssembly2/SOAP_Domain_Msg/Body/FundTransferResponse/FUNDSTRANSFERType/Message"/>
        </assign>
    </mappingDeclaration>
</mappingRoot>
